function ParenthesesValidator(const s: string): boolean;
begin
  var stack := new Stack<char>;
  var pairs := new Dictionary<char, char>;
  pairs.Add(')', '(');
  pairs.Add(']', '[');
  pairs.Add('}', '{');
  foreach var ch in s do
    if pairs.ContainsKey(ch) then
    begin
      if stack.Count = 0 then
        exit(False);
      var top := stack.Pop;
      if top <> pairs[ch] then
        exit(False);
    end
    else
      stack.Push(ch);
  Result := stack.Count = 0;
end;

function PalindromeSublists(const lst: array of integer): integer;
