type
  TFraction = record
    NumIndex, DenIndex: integer;
    Value: real;
  end;

function KthSmallestPrimeFraction(const arr: array of integer; k: integer): (integer, integer);
begin
  var fractions := new List<TFraction>;
  for var j := 1 to arr.Length - 1 do
    for var i := 0 to j - 1 do
    begin
      var item: TFraction;
      item.NumIndex := i;
      item.DenIndex := j;
      item.Value := arr[i] / arr[j];
      fractions.Add(item);
    end;
  fractions.Sort((a, b) -> a.Value.CompareTo(b.Value));
  var frac := fractions[k - 1];
  Result := (arr[frac.NumIndex], arr[frac.DenIndex]);
end;

