function ClosestPairDistance(const points: array of Point2D): real;
begin
  if points.Length < 2 then
    exit(0);
  var minDist := double.MaxValue;
  for var i := 0 to points.Length - 2 do
    for var j := i + 1 to points.Length - 1 do
    begin
      var dx := points[i].X - points[j].X;
      var dy := points[i].Y - points[j].Y;
      var dist := Sqrt(dx * dx + dy * dy);
      if dist < minDist then
        minDist := dist;
    end;
  Result := minDist;
end;

