function MaxSumTwoNonOverlapping(const nums: array of integer; m, n: integer): integer;
begin
  if nums.Length < m + n then
    exit(0);
  var prefix := new integer[nums.Length + 1];
  for var i := 0 to nums.Length - 1 do
    prefix[i + 1] := prefix[i] + nums[i];

  var best := 0;
  var maxLeft := 0;
  for var i := m to nums.Length - n do
  begin
    var leftSum := prefix[i] - prefix[i - m];
    if leftSum > maxLeft then
      maxLeft := leftSum;
    var rightSum := prefix[i + n] - prefix[i];
    if maxLeft + rightSum > best then
      best := maxLeft + rightSum;
  end;

  maxLeft := 0;
  for var i := n to nums.Length - m do
  begin
    var leftSum := prefix[i] - prefix[i - n];
    if leftSum > maxLeft then
      maxLeft := leftSum;
    var rightSum := prefix[i + m] - prefix[i];
    if maxLeft + rightSum > best then
      best := maxLeft + rightSum;
  end;

  Result := best;
end;

