function SmallestSubstringLength(const s, t: string): integer;
begin
  if (s = '') or (t = '') then
    exit(-1);
  var target := new Dictionary<char, integer>;
  foreach var ch in t do
    if target.ContainsKey(ch) then
      target[ch] += 1
    else
      target[ch] := 1;
  var formed := 0;
  var required := target.Count;
  var window := new Dictionary<char, integer>;
  var chars := s.ToCharArray;
  var left := 0;
  var best := integer.MaxValue;
  for var right := 0 to chars.Length - 1 do
  begin
    var ch := chars[right];
    if window.ContainsKey(ch) then
      window[ch] += 1
    else
      window[ch] := 1;
    if target.ContainsKey(ch) and (window[ch] = target[ch]) then
      formed += 1;
    while (left <= right) and (formed = required) do
    begin
      if right - left + 1 < best then
        best := right - left + 1;
      var leftChar := chars[left];
      window[leftChar] -= 1;
      if target.ContainsKey(leftChar) and (window[leftChar] < target[leftChar]) then
        formed -= 1;
      left += 1;
    end;
  end;
  if best = integer.MaxValue then
    Result := -1
  else
    Result := best;
end;

