procedure DFS(var grid: array[,] of integer; r, c: integer);
begin
  if (r < 0) or (c < 0) or (r >= grid.GetLength(0)) or (c >= grid.GetLength(1)) then
    exit;
  if grid[r, c] <> 1 then
    exit;
  grid[r, c] := -1;
  DFS(grid, r + 1, c);
  DFS(grid, r - 1, c);
  DFS(grid, r, c + 1);
  DFS(grid, r, c - 1);
end;

