function NetworkDelayTime(const edges: array of (integer, integer, integer); n, k: integer): integer;
begin
  var graph := new Dictionary<integer, List<(integer, integer)>>;
  foreach var edge in edges do
  begin
    if not graph.ContainsKey(edge.Item1) then
      graph[edge.Item1] := new List<(integer, integer)>;
    graph[edge.Item1].Add((edge.Item2, edge.Item3));
  end;
  var dist := new Dictionary<integer, integer>;
  for var node := 1 to n do
    dist[node] := integer.MaxValue;
  dist[k] := 0;
  var visited := new HashSet<integer>;
  while visited.Count < n do
  begin
    var nextNode := -1;
    var best := integer.MaxValue;
    foreach var kvp in dist do
      if (not visited.Contains(kvp.Key)) and (kvp.Value < best) then
      begin
        best := kvp.Value;
        nextNode := kvp.Key;
      end;
    if nextNode = -1 then
      break;
    visited.Add(nextNode);
    if not graph.ContainsKey(nextNode) then
      continue;
    foreach var edge in graph[nextNode] do
    begin
      var newDist := dist[nextNode] + edge.Item2;
      if newDist < dist[edge.Item1] then
        dist[edge.Item1] := newDist;
    end;
  end;
  if visited.Count <> n then
    exit(-1);
  var maxTime := 0;
  foreach var value in dist.Values do
    if value > maxTime then
      maxTime := value;
  Result := maxTime;
end;

