function FindFirstPosition(const nums: array of integer; target: integer): integer;
begin
  var left := 0;
  var right := nums.Length - 1;
  var ans := -1;
  while left <= right do
  begin
    var mid := (left + right) div 2;
    if nums[mid] >= target then
    begin
      if nums[mid] = target then
        ans := mid;
      right := mid - 1;
    end
    else
      left := mid + 1;
  end;
  Result := ans;
end;

function FindLastPosition(const nums: array of integer; target: integer): integer;
