  while left <= right do
  begin
    var mid := (left + right) div 2;
    if nums[mid] <= target then
    begin
      if nums[mid] = target then
        ans := mid;
      left := mid + 1;
    end
    else
      right := mid - 1;
  end;
  Result := ans;
end;

