function MatrixMult(const a, b: array [,] of integer): array [,] of integer;
begin
  var rows := a.GetLength(0);
  var cols := b.GetLength(1);
  var shared := b.GetLength(0);

  if a.GetLength(1) <> shared then
    raise new System.ArgumentException('Matrix dimensions are not compatible for multiplication');

  Result := new integer[rows, cols];

  for var i := 0 to rows - 1 do
    for var j := 0 to cols - 1 do
    begin
      var sum := 0;
      for var k := 0 to shared - 1 do
        sum += a[i, k] * b[k, j];
      Result[i, j] := sum;
    end;
end;

