function CocktailSort(var nums: array of integer): array of integer;
begin
  var start := 0;
  var last := nums.Length - 1;
  var swapped := True;
  while swapped do
  begin
    swapped := False;
    for var i := start to last - 1 do
      if nums[i] > nums[i + 1] then
      begin
        Swap(nums[i], nums[i + 1]);
        swapped := True;
      end;
    if not swapped then
      break;
    swapped := False;
    last -= 1;
    for var i := last downto start + 1 do
      if nums[i - 1] > nums[i] then
      begin
        Swap(nums[i - 1], nums[i]);
        swapped := True;
      end;
    start += 1;
  end;
  Result := nums;
end;

