function MaxPointsConnection(pointCount: integer; const segments: array of (integer, integer)): integer;
begin
  var graph := new Dictionary<integer, List<integer>>;
  for var i := 0 to pointCount - 1 do
    graph[i] := new List<integer>;
  foreach var seg in segments do
  begin
    graph[seg.Item1].Add(seg.Item2);
    graph[seg.Item2].Add(seg.Item1);
  end;
  var visited := new HashSet<integer>;
  var best := 0;

  for var node := 0 to pointCount - 1 do
    if not visited.Contains(node) then
    begin
      var size := DFS(node, visited, graph);
      if size > best then
        best := size;
    end;
  Result := best;
end;

