function FindHistogramArea(const heights: array of integer): integer;
begin
  var stack := new Stack<integer>;
  var index := 0;
  var maxArea := 0;
  while index < heights.Length do
    if (stack.Count = 0) or (heights[stack.Peek] <= heights[index]) then
    begin
      stack.Push(index);
      index += 1;
    end
    else
    begin
      var top := stack.Pop;
      var width := index;
      if stack.Count > 0 then
        width -= stack.Peek + 1;
      var area := heights[top] * width;
      if area > maxArea then
        maxArea := area;
    end;
  while stack.Count > 0 do
  begin
    var top := stack.Pop;
    var width := index;
    if stack.Count > 0 then
      width -= stack.Peek + 1;
    var area := heights[top] * width;
    if area > maxArea then
      maxArea := area;
  end;
  Result := maxArea;
end;

function BinarySearchFirst(const arr: array of integer; target: integer): integer;
begin
  var left := 0;
  var right := arr.Length - 1;
  var ans := -1;
  while left <= right do
  begin
    var mid := (left + right) div 2;
    if arr[mid] >= target then
    begin
      if arr[mid] = target then
        ans := mid;
      right := mid - 1;
    end
    else
      left := mid + 1;
  end;
  Result := ans;
end;

function BinarySearchLast(const arr: array of integer; target: integer): integer;
begin
  var left := 0;
  var right := arr.Length - 1;
  var ans := -1;
  while left <= right do
  begin
    var mid := (left + right) div 2;
    if arr[mid] <= target then
    begin
      if arr[mid] = target then
        ans := mid;
      left := mid + 1;
    end
    else
      right := mid - 1;
  end;
  Result := ans;
end;

function CountValueOccurrence(const arr: array of integer; target: integer): integer;
begin
  var first := BinarySearchFirst(arr, target);
  if first = -1 then
    exit(0);
  var last := BinarySearchLast(arr, target);
  Result := last - first + 1;
end;

