      left += 1;
    while (left < right) and not chars[right].IsLetter do
      right -= 1;
    if left < right then
    begin
      var temp := chars[left];
      chars[left] := chars[right];
      chars[right] := temp;
      left += 1;
      right -= 1;
    end;
  end;
  Result := new string(chars);
end;

