function IsPossibleDivide(const nums: array of integer; k: integer): boolean;
begin
  if k = 0 then
    exit(False);
  if nums.Length mod k <> 0 then
    exit(False);
  var counts := new SortedDictionary<integer, integer>;
  foreach var num in nums do
    if counts.ContainsKey(num) then
      counts[num] += 1
    else
      counts[num] := 1;
  while counts.Count > 0 do
  begin
    var start := counts.Keys.First;
    for var offset := 0 to k - 1 do
    begin
      var value := start + offset;
      if (not counts.ContainsKey(value)) then
        exit(False);
      counts[value] -= 1;
      if counts[value] = 0 then
        counts.Remove(value);
    end;
  end;
  Result := True;
end;

