  var dp := new integer[n, n];
  for var len := 2 to n do
    for var i := 0 to n - len do
    begin
      var j := i + len - 1;
      if chars[i] = chars[j] then
        if len = 2 then
          dp[i, j] := 0
        else
          dp[i, j] := dp[i + 1, j - 1]
      else
        dp[i, j] := Min(dp[i + 1, j], dp[i, j - 1]) + 1;
    end;
  Result := dp[0, n - 1];
end;

