function Partition(var arr: array of integer; left, right: integer): integer;
begin
  var pivot := arr[right];
  var i := left - 1;
  for var j := left to right - 1 do
    if arr[j] <= pivot then
    begin
      i += 1;
      Swap(arr[i], arr[j]);
    end;
  Swap(arr[i + 1], arr[right]);
  Result := i + 1;
end;

function RandomPartition(var arr: array of integer; left, right: integer): integer;
begin
  var randomGen := new Random;
  var pivotIdx := randomGen.Next(left, right + 1);
  Swap(arr[pivotIdx], arr[right]);
  Result := Partition(arr, left, right);
end;

function QuickSelectInternal(var arr: array of integer; left, right, kIdx: integer): integer;
begin
  var pos := RandomPartition(arr, left, right);
  if pos = kIdx then
    exit(arr[pos]);
  if pos > kIdx then
    exit(QuickSelectInternal(arr, left, pos - 1, kIdx))
  else
    exit(QuickSelectInternal(arr, pos + 1, right, kIdx));
end;

