  for var i := 0 to sorted.Length - 3 do
  begin
    if (i > 0) and (sorted[i] = sorted[i - 1]) then
      continue;
    var left := i + 1;
    var right := sorted.Length - 1;
    while left < right do
    begin
      var sum := sorted[i] + sorted[left] + sorted[right];
      if sum = 0 then
      begin
        resultList.Add(new List<integer>([sorted[i], sorted[left], sorted[right]]));
        while (left < right) and (sorted[left] = sorted[left + 1]) do
          left += 1;
        while (left < right) and (sorted[right] = sorted[right - 1]) do
          right -= 1;
        left += 1;
        right -= 1;
      end
      else if sum < 0 then
        left += 1
      else
        right -= 1;
    end;
  end;
  Result := resultList;
end;

