  for var i := 0 to rows - 1 do
    for var j := 0 to cols - 1 do
      if grid[i][j] = 1 then
      begin
        if (i = 0) or (grid[i - 1][j] = 0) then
          perimeter += 1;
        if (i = rows - 1) or (grid[i + 1][j] = 0) then
          perimeter += 1;
        if (j = 0) or (grid[i][j - 1] = 0) then
