  var diffs := new List<integer>;
  diffs.Add(0);
  for var i := 0 to s.Length - 2 do
    diffs.Add(Abs(Ord(s[i]) - Ord(s[i + 1])));
  diffs.Add(limit + 1);
  var curCost := 0;
  var maxLen := 0;
  var startPos := 0;
  var endPos := 0;
  while (startPos < diffs.Count) and (endPos < diffs.Count - 1) do
  begin
    endPos := Max(startPos, endPos);
    if curCost + diffs[endPos] > limit then
    begin
      curCost -= diffs[startPos];
      startPos += 1;
    end
    else
    begin
      curCost += diffs[endPos];
      endPos += 1;
      maxLen := Max(maxLen, endPos - startPos);
    end;
  end;
  Result := maxLen;
end;

