function UniquePathwaysWithObstacles(const grid: array of array of integer): integer;
begin
  var m := grid.Length;
  if m = 0 then
    exit(0);
  var n := grid[0].Length;
  if grid[0][0] = 1 then
    exit(0);

  var dp := new integer[m, n];
  dp[0, 0] := 1;

  for var i := 1 to m - 1 do
    if (grid[i][0] = 0) and (dp[i - 1, 0] = 1) then
      dp[i, 0] := 1
    else
      dp[i, 0] := 0;

  for var j := 1 to n - 1 do
    if (grid[0][j] = 0) and (dp[0, j - 1] = 1) then
      dp[0, j] := 1
    else
      dp[0, j] := 0;

  for var i := 1 to m - 1 do
    for var j := 1 to n - 1 do
      if grid[i][j] = 0 then
        dp[i, j] := dp[i - 1, j] + dp[i, j - 1]
      else
        dp[i, j] := 0;

  Result := dp[m - 1, n - 1];
end;

