function MaxPointsOnSameLine(const points: array of (integer, integer)): integer;
begin
  if points.Length <= 2 then
    exit(points.Length);
  var maxPoints := 0;
  for var i := 0 to points.Length - 1 do
  begin
    var slopes := new Dictionary<string, integer>;
    var samePoint := 1;
    for var j := i + 1 to points.Length - 1 do
    begin
      if (points[i].Item1 = points[j].Item1) and (points[i].Item2 = points[j].Item2) then
      begin
        samePoint += 1;
        continue;
      end;
      var slope: string;
      if points[i].Item1 = points[j].Item1 then
        slope := 'inf'
      else
      begin
        var rise := points[j].Item2 - points[i].Item2;
        var run := points[j].Item1 - points[i].Item1;
        var g := GCD(rise, run);
        slope := $'{rise div g}/{run div g}';
      end;
      if slopes.ContainsKey(slope) then
        slopes[slope] += 1
      else
        slopes[slope] := 1;
      maxPoints := Max(maxPoints, slopes[slope] + samePoint);
    end;
    maxPoints := Max(maxPoints, samePoint);
  end;
  Result := maxPoints;
end;

