      patCount[ch] += 1
    else
      patCount[ch] := 1;
  var startPos := 0;
  var startIndex := -1;
  var minLen := integer.MaxValue;
  var matchCount := 0;
  var currCount := new Dictionary<char, integer>;
  for var j := 0 to s.Length - 1 do
  begin
    var ch := s[j];
    if currCount.ContainsKey(ch) then
      currCount[ch] += 1
    else
      currCount[ch] := 1;
    if patCount.ContainsKey(ch) and (currCount[ch] <= patCount[ch]) then
      matchCount += 1;
    if matchCount = pat.Length then
    begin
      var currentCharValue: integer;
      while (currCount[s[startPos]] > (patCount.TryGetValue(s[startPos], currentCharValue) ? currentCharValue : 0)) do
      begin
        if currCount[s[startPos]] > 0 then
          currCount[s[startPos]] -= 1;
        startPos += 1;
      end;
      var windowLen := j - startPos + 1;
      if windowLen < minLen then
      begin
        minLen := windowLen;
        startIndex := startPos;
      end;
    end;
  end;
