  var segments := new List<string>;
  var start := numbers[0];
  var finish := numbers[0];

  for var i := 1 to High(numbers) do
    if numbers[i] = finish + 1 then
      finish := numbers[i]
    else
    begin
      if start = finish then
        segments.Add(start.ToString)
      else
        segments.Add($'{start}-{finish}');
      start := numbers[i];
      finish := numbers[i];
