function RepairWall(n: integer; weak, dist: array of integer): integer;
begin
  var length := weak.Length;
  if length = 0 then
    exit(0);
  if dist.Length = 0 then
    exit(-1);

  var extended := weak.ToList;
  for var i := 0 to length - 1 do
    extended.Add(weak[i] + n);

  var answer := integer.MaxValue;

  foreach var permutation in dist.Permutations do
    for var i := 0 to length - 1 do
    begin
      var count := 0;
      var maxPos := extended[i] + permutation[count];
      var covered := true;
      for var j := i to i + length - 1 do
        if maxPos < extended[j] then
        begin
          Inc(count);
          if count >= permutation.Length then
          begin
            covered := false;
            break;
          end;
          maxPos := extended[j] + permutation[count];
        end;
      if covered and (count + 1 < answer) then
        answer := count + 1;
    end;

  if answer = integer.MaxValue then
    Result := -1
  else
    Result := answer;
end;

