type PalInfo = record
  Start, Length: integer;
end;

function ExpandAroundCenter(const s: string; left, right: integer): PalInfo;
begin
  var l := left;
  var r := right;
  while (l >= 0) and (r < s.Length) do
  begin
    if s[l] <> s[r] then
      break;
    Dec(l);
    Inc(r);
  end;
  Result.Start := l + 1;
  Result.Length := r - l - 1;
end;

function LongestPalindromicSubstring(const s: string): string;
begin
  if s.Length < 2 then
    exit(s);
  var best: PalInfo;
  best.Start := 0;
  best.Length := 1;

  for var i := 0 to s.Length - 1 do
  begin
    var info := ExpandAroundCenter(s, i, i);
    if info.Length > best.Length then
      best := info;

    info := ExpandAroundCenter(s, i, i + 1);
    if info.Length > best.Length then
      best := info;
  end;

  Result := s.Substring(best.Start, best.Length);
end;

