function MinCoinsToMakeAmount(const coins: array of integer; amount: integer): integer;
begin
  if amount = 0 then
    exit(0);
  var dp := new integer[amount + 1];
  for var i := 0 to amount do
    dp[i] := integer.MaxValue div 2;
  dp[0] := 0;

  foreach var coin in coins do
    for var value := coin to amount do
      if dp[value - coin] + 1 < dp[value] then
        dp[value] := dp[value - coin] + 1;

  if dp[amount] >= integer.MaxValue div 2 then
    Result := -1
  else
    Result := dp[amount];
end;

