function QuickSelect(const arr: array of integer; k: integer): integer;
begin
  Assert((k >= 1) and (k <= arr.Length));
  if arr.Length = 1 then
    exit(arr[0]);

  var pivot := arr[arr.Length div 2];
  var left := arr.Where(x -> x < pivot).ToArray;
  var middle := arr.Where(x -> x = pivot).ToArray;
  var right := arr.Where(x -> x > pivot).ToArray;

  if k <= left.Length then
    Result := QuickSelect(left, k)
  else if k > left.Length + middle.Length then
    Result := QuickSelect(right, k - left.Length - middle.Length)
  else
    Result := middle[0];
end;

function FindInsertPosition(const sortedList: array of integer; value: integer): integer;
