function RearrangeString(const s: string): string;
begin
  if s = '' then
    exit('');
  var freq := new Dictionary<char, integer>;
  foreach var ch in s do
  begin
    if not freq.ContainsKey(ch) then
      freq[ch] := 0;
    freq[ch] := freq[ch] + 1;
  end;

  var sb := new StringBuilder;
  var lastChar := #0;

  while sb.Length < s.Length do
  begin
    var nextChar := #0;
    var bestCount := -1;

    // Greedy pick highest-frequency char that differs from previous one
    foreach var kvp in freq.ToArray do
      if (kvp.Value > bestCount) and ((sb.Length = 0) or (kvp.Key <> lastChar)) and (kvp.Value > 0) then
      begin
        nextChar := kvp.Key;
        bestCount := kvp.Value;
      end;

    if bestCount = -1 then
      exit('');

    sb.Append(nextChar);
    lastChar := nextChar;
    freq[nextChar] := bestCount - 1;
    if freq[nextChar] = 0 then
      freq.Remove(nextChar);
  end;

  Result := sb.ToString;
end;

