procedure IslandDfs(const matrix: array[,] of integer; var visited: array[,] of boolean; rows, cols, r, c: integer);
begin
  if (r < 0) or (c < 0) or (r >= rows) or (c >= cols) then
    exit;
  if (matrix[r, c] = 0) or visited[r, c] then
    exit;
  visited[r, c] := true;
  IslandDfs(matrix, visited, rows, cols, r + 1, c);
  IslandDfs(matrix, visited, rows, cols, r - 1, c);
  IslandDfs(matrix, visited, rows, cols, r, c + 1);
  IslandDfs(matrix, visited, rows, cols, r, c - 1);
end;

function IslandCounter(const matrix: array[,] of integer): integer;
begin
  if matrix = nil then
    exit(0);
  var rows := matrix.GetLength(0);
  var cols := matrix.GetLength(1);
  if (rows = 0) or (cols = 0) then
    exit(0);

  var visited := new boolean[rows, cols];
  var islands := 0;
  for var r := 0 to rows - 1 do
    for var c := 0 to cols - 1 do
      if (matrix[r, c] = 1) and not visited[r, c] then
      begin
        Inc(islands);
        IslandDfs(matrix, visited, rows, cols, r, c);
      end;
  Result := islands;
end;

