type
  TreeNode = class
  public
    Children: array of TreeNode;
    constructor Create;
  end;

  Tree = class
  private
    fRoot: TreeNode;
  public
    constructor Create;
    procedure Insert(num: integer);
    function Query(num: integer): integer;
  end;

constructor TreeNode.Create;
begin
  Children[0] := nil;
  Children[1] := nil;
end;

constructor Tree.Create;
begin
  fRoot := new TreeNode;
end;

procedure Tree.Insert(num: integer);
begin
  var node := fRoot;
  for var i := 31 downto 0 do
  begin
    var bit := (num shr i) and 1;
    if node.Children[bit] = nil then
      node.Children[bit] := new TreeNode;
    node := node.Children[bit];
  end;
end;

function Tree.Query(num: integer): integer;
begin
  var node := fRoot;
  var xorValue := 0;
  for var i := 31 downto 0 do
  begin
    var bit := (num shr i) and 1;
    var toggled := 1 - bit;
    if node.Children[toggled] <> nil then
    begin
      xorValue := xorValue or (1 shl i);
      node := node.Children[toggled];
    end
    else if node.Children[bit] <> nil then
      node := node.Children[bit]
    else
      break;
  end;
  Result := xorValue;
end;

