function ZeroSumTriplets(const nums: array of integer): array of array of integer;
begin
  var resultList := new List<array of integer>;
  if nums.Length < 3 then
  begin
    Result := resultList.ToArray;
    exit;
  end;

  var sorted := nums.Order.ToArray;
  for var i := 0 to sorted.Length - 3 do
  begin
    if (i > 0) and (sorted[i] = sorted[i - 1]) then
      continue;
    var left := i + 1;
    var right := sorted.Length - 1;
    while left < right do
    begin
      var sum := sorted[i] + sorted[left] + sorted[right];
      if sum = 0 then
      begin
        resultList.Add(Arr(sorted[i], sorted[left], sorted[right]));
        Inc(left);
        Dec(right);
        while (left < right) and (sorted[left] = sorted[left - 1]) do
          Inc(left);
        while (left < right) and (sorted[right] = sorted[right + 1]) do
          Dec(right);
      end
      else if sum < 0 then
        Inc(left)
      else
        Dec(right);
