  var prefix := 0;
  var maxLength := 0;
  for var i := 0 to arr.Length - 1 do
  begin
    prefix += arr[i];
    if prefix = k then
      maxLength := Max(maxLength, i + 1);
    if firstIndex.ContainsKey(prefix - k) then
      maxLength := Max(maxLength, i - firstIndex[prefix - k]);
    if not firstIndex.ContainsKey(prefix) then
      firstIndex[prefix] := i;
  end;
  Result := maxLength;
end;

