  end;
  var chars := new HashSet<char>(s.ToCharArray);
  for var i := 0 to s.Length - 1 do
  begin
    var c := s[i];
    var upper := System.Char.ToUpper(c);
    var lower := System.Char.ToLower(c);
    if chars.Contains(upper) and chars.Contains(lower) then
      continue;
    var left := LongestNiceSubstringHelper(s.Substring(0, i));
    var right := LongestNiceSubstringHelper(s.Substring(i + 1));
    if left.Length >= right.Length then
    begin
      Result := left;
      exit;
    end
    else
    begin
      Result := right;
      exit;
    end;
  end;
  Result := s;
end;

