  pairs[')'] := '(';
  var stack := new Stack<char>;
  foreach var ch in s do
    if not pairs.ContainsKey(ch) then
      stack.Push(ch)
    else
    begin
      if (stack.Count = 0) or (stack.Peek <> pairs[ch]) then
        exit(false);
      stack.Pop;
    end;
