function LongestSubstringWithKUnique(const s: string; k: integer): integer;
begin
  if k <= 0 then
  begin
    Result := 0;
    exit;
  end;
  var counts := new Dictionary<char, integer>;
  var left := 0;
  var maxLength := 0;
  for var right := 0 to s.Length - 1 do
  begin
    var ch := s[right];
    if counts.ContainsKey(ch) then
      counts[ch] := counts[ch] + 1
    else
      counts[ch] := 1;
    while counts.Count > k do
    begin
      var leftChar := s[left];
      counts[leftChar] := counts[leftChar] - 1;
      if counts[leftChar] = 0 then
        counts.Remove(leftChar);
      Inc(left);
    end;
    if counts.Count = k then
    begin
      var currentLength := right - left + 1;
      if currentLength > maxLength then
        maxLength := currentLength;
    end;
  end;
  Result := maxLength;
end;

