  var sumval := 0;
  for var i := 0 to n - 1 do
  begin
    dp[i,0] := matrix[i][0];
    sumval += dp[i,0];
  end;
  for var j := 1 to m - 1 do
  begin
    dp[0,j] := matrix[0][j];
    sumval += dp[0,j];
  end;
  for var i := 1 to n - 1 do
    for var j := 1 to m - 1 do
    begin
      if matrix[i][j] = 1 then
      begin
        dp[i,j] := Min(dp[i-1,j], Min(dp[i,j-1], dp[i-1,j-1])) + 1;
