function UniquePermutations(s: string): biginteger;
begin
  var counts := new Dictionary<integer, integer>;
  foreach var ch in s do
  begin
    var code := Ord(ch);
    if counts.ContainsKey(code) then counts[code] += 1
    else counts[code] := 1;
  end;
  var n := s.Length;
  var res := BigInteger.One;
  // factorial using BigInteger
  var fact : function(k: integer): BigInteger := k ->
    begin
      var res := BigInteger.One;
      for var i := 2 to k do res := res * i;
      Result := res;
    end;
  res := fact(n);
  foreach var kv in counts do
    res := res / fact(kv.Value);
  Result := res;
end;

