  var dp := new integer[arr.Length];
  dp[0] := arr[0];
  dp[1] := Max(arr[0], arr[1]);
  for var i := 2 to arr.Length - 1 do
    dp[i] := Max(dp[i-1], dp[i-2] + arr[i]);
  Result := dp[arr.Length - 1];
end;

function IsPossibleTarget(target: array of integer): boolean;
begin
  // Use a max-heap simulation using SortedDictionary of counts (since no built-in heap)
  var total := 0;
  foreach var v in target do total += v;
  var dict := new Dictionary<integer, integer>;
  foreach var v in target do
    if dict.ContainsKey(v) then dict[v] += 1 else dict[v] := 1;
  while True do
  begin
    // get current max
    var num := dict.Keys.Max;
    // remove one occurrence
    dict[num] -= 1;
    if dict[num] = 0 then dict.Remove(num);
    total -= num;
    if num = 1 then begin Result := True; exit; end;
    if (total = 1) then begin Result := True; exit; end;
    if (num < total) or (total = 0) or (num mod total = 0) then begin Result := False; exit; end;
    var newnum := num mod total;
    if dict.ContainsKey(newnum) then dict[newnum] += 1 else dict[newnum] := 1;
    total += newnum;
  end;
end;

