  var MAX := 100000; // a cap similar to original implementation; adjust as needed
  var counts := new Dictionary<integer, integer>;
  foreach var x in A do
    if counts.ContainsKey(x) then counts[x] += 1 else counts[x] := 1;
  var taken := new Queue<integer>;
  var ans := 0;
  for var i := 0 to MAX - 1 do
  begin
    if counts.ContainsKey(i) and (counts[i] > 1) then
      for var t := 1 to counts[i] - 1 do
        taken.Enqueue(i)
    else if (taken.Count > 0) and (not counts.ContainsKey(i) or (counts[i] = 0)) then
    begin
      ans += i - taken.Dequeue;
    end;
  end;
  Result := ans;
end;

