function CountPalSub(s: string): integer;
begin
  var cnt := 0;
  // expand-around-center without local functions
  for var center := 0 to s.Length - 1 do
  begin
    // odd-length
    var l := center;
    var r := center;
    while (l >= 0) and (r < s.Length) and (s[l] = s[r]) do
    begin
      cnt += 1;
      l -= 1;
      r += 1;
    end;

    // even-length
    l := center;
    r := center + 1;
    while (l >= 0) and (r < s.Length) and (s[l] = s[r]) do
    begin
      cnt += 1;
      l -= 1;
      r += 1;
    end;
  end;

  Result := cnt;
end;

