  begin
    if a[i] < b[j] then
    begin
      merged.Add(a[i]);
      i += 1;
    end
    else
    begin
      merged.Add(b[j]);
      j += 1;
    end;
  end;

  while i < a.Length do
  begin
    merged.Add(a[i]);
    i += 1;
  end;

  while j < b.Length do
  begin
    merged.Add(b[j]);
    j += 1;
  end;

  Result := merged.ToArray;
end;

function LongestRepeatUnitLen(s: string): integer;
begin
  // Find the longest prefix whose repetition forms the whole string.
  var n := s.Length;
  if n = 0 then
  begin
    Result := 0; exit;
  end;
  // Check divisors of n in descending order to find longest repeating unit
  var bestLen := 1;
  var d := n;
  while d >= 1 do
  begin
    if (n mod d = 0) then
    begin
      var rep := s.Substring(0, d);
      var ok := True;
      var k := 1;
      while (k * d) < n do
      begin
        if s.Substring(k * d, d) <> rep then
        begin
          ok := False; break;
        end;
        k += 1;
      end;
      if ok then
      begin
        bestLen := d;
        // since we iterate descending, the first valid d is the longest
        Result := bestLen; exit;
      end;
    end;
    d -= 1;
  end;
  Result := bestLen;
end;

function MinRemoveIntervals(intervals: array of array of integer): integer;
begin
  if (intervals = nil) or (intervals.Length = 0) then
  begin
    Result := 0; exit;
  end;
  // Sort intervals by end ascending
  var idxs := new List<integer>;
  for var i := 0 to intervals.Length - 1 do idxs.Add(i);
  idxs.Sort((a,b)->
  begin
    var ea := intervals[a][1];
    var eb := intervals[b][1];
    if ea < eb then Result := -1 else if ea > eb then Result := 1 else Result := 0;
  end);

  var kept := 0;
  var lastEnd := -MaxInt; // very small
  foreach var i in idxs do
  begin
    var st := intervals[i][0];
    var en := intervals[i][1];
    if st >= lastEnd then
    begin
      kept += 1;
      lastEnd := en;
    end;
  end;
  Result := intervals.Length - kept;
end;

function MinOpsReduceToZero(nums: array of integer; x: integer): integer;
begin
  // Equivalent: find longest subarray whose sum is total - x
  var n := nums.Length;
  var total := 0;
  for var i := 0 to n - 1 do total += nums[i];
  var target := total - x;
  if target < 0 then begin Result := -1; exit; end;
  if target = 0 then begin Result := n; exit; end;

  var left := 0;
  var cur := 0;
  var bestLen := -1;
  for var right := 0 to n - 1 do
  begin
    cur += nums[right];
    while (left <= right) and (cur > target) do
    begin
      cur -= nums[left];
      left += 1;
    end;
    if cur = target then
      bestLen := Max(bestLen, right - left + 1);
  end;
  if bestLen = -1 then Result := -1
  else Result := n - bestLen;
end;

function MaxSubarraySum(arr: array of integer): integer;
begin
  if (arr = nil) or (arr.Length = 0) then begin Result := 0; exit; end;
  var best := arr[0];
  var cur := arr[0];
  for var i := 1 to arr.Length - 1 do
  begin
    cur := Max(arr[i], cur + arr[i]);
    best := Max(best, cur);
  end;
  Result := best;
end;

function NextPowerOfTwo(n: integer): integer;
begin
  if n <= 1 then begin Result := 1; exit; end;
  var v := 1;
  while v < n do v := v shl 1;
  Result := v;
end;

function IsAlnumPalindrome(s: string): boolean;
begin
  var i := 0; var j := s.Length - 1;
  while i < j do
  begin
    while (i < j) and (not Char.IsLetterOrDigit(s[i])) do i += 1;
    while (i < j) and (not Char.IsLetterOrDigit(s[j])) do j -= 1;
    if i < j then
    begin
      if Char.ToLower(s[i]) <> Char.ToLower(s[j]) then
      begin
        Result := False; exit;
      end;
      i += 1; j -= 1;
    end;
  end;
  Result := True;
end;

function HasAdjacentZeros(a: array of integer): boolean;
begin
  for var i := 0 to a.Length - 2 do
    if (a[i] = 0) and (a[i+1] = 0) then
    begin Result := True; exit; end;
  Result := False;
end;

function SumBinaryDigits(x: integer): integer;
begin
  var cnt := 0;
  var v := Abs(x);
  while v > 0 do
  begin
    if (v and 1) = 1 then cnt += 1;
    v := v shr 1;
  end;
  Result := cnt;
end;

function MinWindowSubstring(s, t: string): string;
begin
  if (t = '') or (s = '') then begin Result := ''; exit; end;
  var need := new Dictionary<char,integer>;
  foreach var ch in t do
    if need.ContainsKey(ch) then need[ch] += 1 else need[ch] := 1;
  var have := 0;
  var required := need.Count;
  var left := 0;
  var minLen := MaxInt;
  var minL := 0;
  var windowCounts := new Dictionary<char,integer>;

  for var right := 0 to s.Length - 1 do
  begin
    var rc := s[right];
    if windowCounts.ContainsKey(rc) then windowCounts[rc] += 1 else windowCounts[rc] := 1;
    if need.ContainsKey(rc) and (windowCounts[rc] = need[rc]) then
      have += 1;

    while (have = required) and (left <= right) do
    begin
      var curLen := right - left + 1;
      if curLen < minLen then
      begin
        minLen := curLen; minL := left;
      end;
      var lc := s[left];
      windowCounts[lc] -= 1;
      if need.ContainsKey(lc) and (windowCounts[lc] < need[lc]) then
        have -= 1;
      left += 1;
    end;
  end;

  if minLen = MaxInt then Result := '' else Result := s.Substring(minL, minLen);
end;

function LargestBinaryImageOverlap(A, B: array of array of integer): integer;
begin
  var n := A.Length;
  if (n = 0) then begin Result := 0; exit; end;
  var m := A[0].Length;
  var best := 0;
  // Try all translations: shiftB relative to A
  for var dx := -(n-1) to (n-1) do
    for var dy := -(m-1) to (m-1) do
    begin
      var cur := 0;
      for var i := 0 to n - 1 do
        for var j := 0 to m - 1 do
        begin
          var ii := i + dx;
          var jj := j + dy;
          if (ii >= 0) and (ii < n) and (jj >= 0) and (jj < m) then
            if (A[i][j] = 1) and (B[ii][jj] = 1) then cur += 1;
        end;
      if cur > best then best := cur;
    end;
  Result := best;
end;

function RectanglesOverlap(r1, r2: array of integer): boolean;
begin
  // Each rectangle given as [x1,y1,x2,y2] where (x1,y1) is bottom-left and (x2,y2) is top-right
  if (r1[2] <= r2[0]) or (r2[2] <= r1[0]) then begin Result := False; exit; end; // one is left of other
  if (r1[3] <= r2[1]) or (r2[3] <= r1[1]) then begin Result := False; exit; end; // one is below other
  Result := True;
end;

function ReplaceAll(s, pattern, replacement: string): string;
begin
  if (pattern = '') then begin Result := s; exit; end;
  // Use .Replace which replaces all non-overlapping occurrences
  Result := s.Replace(pattern, replacement);
end;

function CanPartition(nums: array of integer): boolean;
begin
  var total := 0;
  foreach var v in nums do total += v;
  if (total mod 2) <> 0 then begin Result := False; exit; end;
  var target := total div 2;
  var reachable := new boolean[target + 1];
  reachable[0] := True;
  foreach var v in nums do
  begin
    for var s := target downto v do
      if reachable[s - v] then reachable[s] := True;
  end;
  Result := reachable[target];
end;

function ScaleToMatrix(lists: array of array of integer; scalar: integer): array [,] of integer;
begin
  var rows := lists.Length;
  if rows = 0 then
    exit(new integer[0, 0]);
  var cols := lists[0].Length;
  Result := new integer[rows, cols];
  for var i := 0 to rows - 1 do
    for var j := 0 to cols - 1 do
      Result[i, j] := lists[i][j] * scalar;
end;

function ElementwiseProduct(a, b: array of integer): array of integer;
begin
  var n := Min(a.Length, b.Length);
  var out := new integer[n - 1];
  for var i := 0 to n - 1 do
    out[i] := a[i] * b[i];
  Result := out;
end;

function RepeatedNTimes(nums: array of integer): integer;
begin
  var counts := new Dictionary<integer,integer>;
  foreach var v in nums do
  begin
    if counts.ContainsKey(v) then counts[v] += 1 else counts[v] := 1;
    if counts[v] > 1 then // the repeated element will quickly exceed 1 often
    begin
      if counts[v] >= nums.Length div 2 then begin Result := v; exit; end;
    end;
  end;
  // fallback: find max count
  var best := nums[0]; var bestCnt := 0;
  foreach var kv in counts do
    if kv.Value > bestCnt then begin bestCnt := kv.Value; best := kv.Key; end;
  Result := best;
end;

function SmallestVertices(n: integer; edges: array of array of integer): array of integer;
begin
  var indeg := new integer[n - 1];
  for var i := 0 to n - 1 do indeg[i] := 0;
  for var e := 0 to edges.Length - 1 do
  begin
    var toNode := edges[e][1];
    indeg[toNode] += 1;
  end;
  var res := new List<integer>;
  for var i := 0 to n - 1 do
    if indeg[i] = 0 then res.Add(i);
  Result := res.ToArray;
end;

function MinPerimeterForArea(areaVal: integer): integer;
begin
  if areaVal <= 0 then begin Result := 0; exit; end;
  var best := MaxInt;
  var i := 1;
  while i * i <= areaVal do
  begin
    if (areaVal mod i) = 0 then
    begin
      var j := areaVal div i;
      var p := 2 * (i + j);
      if p < best then best := p;
    end;
    i += 1;
  end;
  Result := best;
end;

function ModPow(baseVal: Int64; exponentVal: Int64; modulusVal: Int64): Int64;
begin
  if modulusVal = 1 then begin Result := 0; exit; end;
  var res := Int64(1) mod modulusVal;
  var a := (baseVal mod modulusVal + modulusVal) mod modulusVal;
  var e := exponentVal;
  while e > 0 do
  begin
    if (e and 1) = 1 then res := (res * a) mod modulusVal;
    a := (a * a) mod modulusVal;
    e := e shr 1;
  end;
  Result := res;
end;

function NegativesToSquares(nums: array of integer): Dictionary<integer, integer>;
begin
  var map := new Dictionary<integer, integer>;
  foreach var v in nums do
    if v < 0 then
      if not map.ContainsKey(v) then map[v] := v * v;
  Result := map;
end;

function MaxSubarraySumK(arr: array of integer; k: integer): integer;
begin
  if (arr = nil) or (k <= 0) or (k > arr.Length) then
  begin
    Result := 0;
    exit;
  end;

  var windowSum := 0;
  for var i := 0 to k - 1 do
    windowSum += arr[i];
  var best := windowSum;

  for var i := k to arr.Length - 1 do
  begin
    windowSum := windowSum + arr[i] - arr[i - k];
    if windowSum > best then best := windowSum;
  end;

  Result := best;
end;

function ReverseWordsInStrings(stringsArr: array of string): array of string;
begin
  if stringsArr = nil then
  begin
    Result := new string[0];
    exit;
  end;
  var n := stringsArr.Length;
  SetLength(Result, n);
  for var i := 0 to n - 1 do
  begin
    var words := stringsArr[i].Split(' ');
    var outWords := new List<string>;
    for var w := 0 to words.Length - 1 do
      outWords.Add(new string(words[w].ToCharArray.Reverse.ToArray));
    Result[i] := String.Join(' ', outWords);
  end;
end;

function MaxDictDepth(obj: object): integer;
begin
  // Computes maximum nesting depth of dictionaries. Non-dictionary values count as depth 0.
  if obj = nil then begin Result := 0; exit; end;
  var dictType := typeof(System.Collections.Generic.Dictionary<string, object>);
  if obj.GetType() <> dictType then
  begin
    // If it's not the expected dictionary type, check assignability
    if not (obj is System.Collections.Generic.IDictionary<string, object>) then
    begin
      Result := 0; exit;
    end;
  end;

  var queue := new List<object>;
  queue.Add(obj);
  var depth := 0;
  while queue.Count > 0 do
  begin
    var nextLevel := new List<object>;
    foreach var item in queue do
    begin
      var d := item as System.Collections.Generic.IDictionary<string, object>;
      if d <> nil then
      begin
        foreach var kv in d do
          if (kv.Value <> nil) and (kv.Value is System.Collections.Generic.IDictionary<string, object>) then
            nextLevel.Add(kv.Value);
      end;
    end;
    depth += 1;
    queue := nextLevel;
  end;
  Result := depth;
end;

function RearrangeNoAdjacent(s: string): string;
begin
  if s = '' then begin Result := ''; exit; end;
  var counts := new Dictionary<char,integer>;
  foreach var ch in s do
    if counts.ContainsKey(ch) then counts[ch] += 1 else counts[ch] := 1;

  var maxCount := 0; var maxChar := #0;
  foreach var kv in counts do
    if kv.Value > maxCount then begin maxCount := kv.Value; maxChar := kv.Key; end;

  if maxCount > (s.Length + 1) div 2 then begin Result := ''; exit; end;

  // Greedy rebuild using a list of pairs sorted by remaining count
  var resultChars := new List<char>;
  var pq := new List<(char,integer)>;
  foreach var kv in counts do pq.Add((kv.Key, kv.Value));

  while pq.Count > 0 do
  begin
    pq.Sort((a,b)-> if a.Item2 > b.Item2 then Result := -1 else if a.Item2 < b.Item2 then Result := 1 else Result := 0);
    var first := pq[0];
    // pick first
    resultChars.Add(first.Item1);
    first := (first.Item1, first.Item2 - 1);
    pq.RemoveAt(0);
    if pq.Count = 0 then
    begin
      if first.Item2 > 0 then begin Result := ''; exit; end;
      break;
    end;
    // pick second
    pq.Sort((a,b)-> if a.Item2 > b.Item2 then Result := -1 else if a.Item2 < b.Item2 then Result := 1 else Result := 0);
    var second := pq[0];
    resultChars.Add(second.Item1);
    second := (second.Item1, second.Item2 - 1);
    pq.RemoveAt(0);
    if first.Item2 > 0 then pq.Add(first);
    if second.Item2 > 0 then pq.Add(second);
  end;

  Result := new string(resultChars.ToArray);
end;

function IsBalancedParentheses(s: string): boolean;
begin
  var st := new List<char>;
  foreach var ch in s do
  begin
    if (ch = '(') or (ch = '[') or (ch = '{') then st.Add(ch)
    else if (ch = ')') or (ch = ']') or (ch = '}') then
    begin
      if st.Count = 0 then begin Result := False; exit; end;
      var top := st[st.Count - 1]; st.RemoveAt(st.Count - 1);
      if (ch = ')') and (top <> '(') then begin Result := False; exit; end;
      if (ch = ']') and (top <> '[') then begin Result := False; exit; end;
      if (ch = '}') and (top <> '{') then begin Result := False; exit; end;
    end;
  end;
  Result := st.Count = 0;
end;

function LargestEqualZeroOneSubarray(arr: array of integer): integer;
begin
  // Return length of largest subarray with equal 0s and 1s
  var n := arr.Length;
  if n = 0 then begin Result := 0; exit; end;
  var sum := 0;
  var earliest := new Dictionary<integer, integer>;
  earliest[0] := -1;
  var best := 0;
  for var i := 0 to n - 1 do
  begin
    if arr[i] = 0 then sum -= 1 else sum += 1;
    if earliest.ContainsKey(sum) then
      best := Max(best, i - earliest[sum])
    else
      earliest[sum] := i;
  end;
  Result := best;
end;

function CanPermutePalindrome(s: string): boolean;
begin
  var counts := new Dictionary<char,integer>;
  foreach var ch in s do
    if counts.ContainsKey(ch) then counts[ch] += 1 else counts[ch] := 1;
  var oddCount := 0;
  foreach var kv in counts do
    if (kv.Value and 1) = 1 then oddCount += 1;
  // palindrome permutation allowed: at most one odd count
  Result := oddCount <= 1;
end;

function DailyAverages(hourly: array of double; hoursPerDay: integer): array of double;
begin
  if (hourly = nil) or (hoursPerDay <= 0) then
  begin
    Result := new double[0]; exit;
  end;
  var days := hourly.Length div hoursPerDay;
  SetLength(Result, days);
  for var d := 0 to days - 1 do
  begin
    var sum := 0.0;
    for var h := 0 to hoursPerDay - 1 do
      sum += hourly[d * hoursPerDay + h];
    Result[d] := sum / hoursPerDay;
  end;
end;

function MinMaxDigits(n: Int64): array of integer;
begin
  var v := Abs(n);
  if v = 0 then
  begin
    SetLength(Result, 2);
    Result[0] := 0; Result[1] := 0; exit;
  end;
  var minD := 9; var maxD := 0;
  while v > 0 do
  begin
    var d := v mod 10;
    if d < minD then minD := d;
    if d > maxD then maxD := d;
    v := v div 10;
  end;
  SetLength(Result, 2);
  Result[0] := minD; Result[1] := maxD;
end;

function TopKLargest(nums: array of integer; k: integer): array of integer;
begin
  if (nums = nil) or (k <= 0) then
  begin
    Result := new integer[0]; exit;
  end;
  var n := nums.Length;
  if k >= n then
  begin
    var all := nums.Clone() as array of integer;
    &Array.Sort(all);
    &Array.Reverse(all);
    Result := all; exit;
  end;

  // Use a small min-heap simulation via sorted list of size k
  var topList := new List<integer>;
  for var i := 0 to n - 1 do
  begin
    if topList.Count < k then
    begin
      topList.Add(nums[i]);
      topList.Sort;
    end
    else if nums[i] > topList[0] then
    begin
      topList[0] := nums[i];
      topList.Sort;
    end;
  end;
  // topList is sorted ascending -> reverse to get descending
  topList.Reverse;
  Result := topList.ToArray;
end;

function Mincoinchange(coins: array of integer; amount: integer): integer;
begin

  var dp := new integer[amount + 1];
  var inf := amount + 1;
  for var i := 0 to amount do dp[i] := inf;
  dp[0] := 0;
  for var i := 1 to amount do
  begin
    for var c := 0 to coins.Length - 1 do
      if coins[c] <= i then
        dp[i] := Min(dp[i], dp[i - coins[c]] + 1);
  end;
  if dp[amount] > amount then Result := -1 else Result := dp[amount];
end;

function ValidatePassword(password: string): boolean;
begin

var hasLower := False;
var hasUpper := False;
var hasDigit := False;
var hasSpecial := False;
if password.Length < 8 then begin Result := False; exit; end;
var specials := '!@#$%^&*';
foreach var ch in password do
begin
  if Char.IsLower(ch) then hasLower := True
  else if Char.IsUpper(ch) then hasUpper := True
  else if Char.IsDigit(ch) then hasDigit := True
  else if specials.IndexOf(ch) >= 0 then hasSpecial := True;
end;
Result := hasLower and hasUpper and hasDigit and hasSpecial;
end;

function BubbleSortDesc(arr: array of integer): array of integer;
begin

var n := arr.Length;
if n <= 1 then begin Result := arr; exit; end;
var a := arr.Clone() as array of integer;
for var i := 0 to n - 2 do
  for var j := 0 to n - 2 - i do
    if a[j] < a[j+1] then
    begin
      var tmp := a[j]; a[j] := a[j+1]; a[j+1] := tmp;
    end;
Result := a;
end;

function KDiffPairs(nums: array of integer; k: integer): integer;
begin

var cnt := 0;
var freq := new Dictionary<integer,integer>;
foreach var v in nums do if freq.ContainsKey(v) then freq[v] += 1 else freq[v] := 1;
if k = 0 then
begin
  foreach var kv in freq do if kv.Value > 1 then cnt += 1;
  Result := cnt; exit;
end;
foreach var kv in freq do if freq.ContainsKey(kv.Key + k) then cnt += 1;
Result := cnt;
end;

function AlphabeticCount(s: string): integer;
begin

var c := 0;
foreach var ch in s do if Char.IsLetter(ch) then c += 1;
Result := c;
end;

function ReverseAndMoveDigits(stringsArr: array of string): array of string;
begin

if stringsArr = nil then begin Result := new string[0]; exit; end;
var out := new string[stringsArr.Length - 1];
for var i := 0 to stringsArr.Length - 1 do
begin
  var s := stringsArr[i];
  var letters := new List<char>; var digits := new List<char>;
  foreach var ch in s do if Char.IsDigit(ch) then digits.Add(ch) else letters.Add(ch);
  letters.Reverse; digits.Reverse;
  Result[i] := new string(letters.ToArray) + new string(digits.ToArray);
end;
end;

function SignList(numbers: array of integer): array of string;
begin

var out := new string[numbers.Length - 1];
for var i := 0 to numbers.Length - 1 do
  if numbers[i] > 0 then out[i] := '+' else if numbers[i] < 0 then out[i] := '-' else out[i] := '0';
Result := out;
end;
